def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    if not cells:
        return out

    rmin = min(r for r, c in cells)
    rmax = max(r for r, c in cells)

    # Remove the marker shape.
    for r in range(h):
        for c in range(w):
            if out[r][c] == 6:
                out[r][c] = 0

    # Append a vertically reflected copy of the 4-shape.
    for r, c in cells:
        rr = 2 * rmax + 1 - r
        if 0 <= rr < h:
            out[rr][c] = 4
    return out
